 module:="web"; if strings.Contains(p.Path+p.NewPath," api/"){module="api"}
 sets:=[]ChangeSet{{ID:"cs",Spec:"alpha",ResolvedBase:"b",ResolvedHead:"h",Commits:[]string{"c"},DiffDigest:"sha256:"+strings.Repeat("a",64),Paths:[]ObservedPath{p}}}
