func TestB30R4ProbeHistoryLoss(t *testing.T){
 s,_:=factsWithResultsFile(t,[]DeliveryValidationResult{{ID:"x",Module:"api",Check:"test",EvidenceClass:"unit",Outcome:"pass"}})
 factsGit(t,s.Root,"checkout","-q","-b","side")
 os.MkdirAll(filepath.Join(s.Root,"api"),0755);os.WriteFile(filepath.Join(s.Root,"api/server.go"),[]byte("package api\n"),0644)
 factsGit(t,s.Root,"add","api/server.go");factsGit(t,s.Root,"commit","-q","-m","side","-m","POSE-Spec: alpha")
 // Read the actual side commit from the canonical history reader.
 commits,e:=SpecTrailerCommits(s.Root,"alpha");if e!=nil||len(commits)!=1{t.Fatal(e,commits)}
 graph,_:=s.GetDeliveryIntegrity("");graph.ChangeSets[0].Commits=commits;graph.ChangeSets[0].ResolvedHead=commits[0];graph.ChangeSets[0].Selector="trailers:alpha"
 graph.ValidationResults[0].GitHead=commits[0];graph.ValidationResults[0].ScopeProvenance=map[string]string{"alpha":ScopedDeliveryProvenanceDigest(graph,"alpha")}
 r:=graph.ValidationResults[0]
 run:=map[string]any{"schema_version":1,"git_head":r.GitHead,"generated_at":r.GeneratedAt,"provenance_digest":r.ProvenanceDigest,"scope_provenance":r.ScopeProvenance,"checks":[]map[string]any{{"id":r.ID,"module":r.Module,"name":r.Check,"severity":r.Severity,"outcome":r.Outcome,"evidence_class":r.EvidenceClass}}}
 raw,_:=json.Marshal(run);os.WriteFile(filepath.Join(s.Root,factsResultsPath),raw,0644)
 raw,_=json.Marshal(graph);outs:=map[string][]byte{};for _,n:=range IndexGenerationFiles{outs[n]=[]byte("{}\n")};outs["delivery-integrity.json"]=raw
 if _,e:=s.PublishIndexGeneration(outs,IndexInputBindings(s.Root));e!=nil{t.Fatal(e)}
 before,_:=s.DeriveSpecFacts("alpha");if before.Freshness.Status!=SpecFactsFresh{t.Fatal(before.Freshness)}
 factsGit(t,s.Root,"checkout","-q","-");factsGit(t,s.Root,"branch","-D","side")
 after,e:=s.DeriveSpecFacts("alpha");if e!=nil||after.Freshness.Status!=SpecFactsFresh||len(after.Checks)!=1{t.Fatalf("not reproduced %+v %v",after,e)}
 current,_:=SpecTrailerCommits(s.Root,"alpha");if len(current)!=0{t.Fatal(current)}
 t.Logf("lost attributed commit; still freshness=%+v associated=%+v",after.Freshness,after.Checks)
}
