func TestB30R4ProbeGenerationIdentity(t *testing.T){
 s,_:=factsWithResultsFile(t,[]DeliveryValidationResult{{ID:"x",Module:"api",Check:"test",EvidenceClass:"unit",Outcome:"pass"}})
 pinned:=s.PinIndexes();old:=pinned.indexPin.Descriptor.GenerationID
 graph,e:=s.GetDeliveryIntegrity("");if e!=nil{t.Fatal(e)};graph.ChangeSets[0].Paths=[]ObservedPath{{Action:"modified",Path:"web/new.go"}}
 outputs:=map[string][]byte{};for _,n:=range IndexGenerationFiles{outputs[n]=[]byte("{}\n")};outputs["delivery-integrity.json"],_=json.Marshal(graph)
 receipt,e:=s.PublishIndexGeneration(outputs,IndexInputBindings(s.Root));if e!=nil{t.Fatal(e)};if old==receipt.GenerationID{t.Fatal("same generation")}
 f,e:=pinned.DeriveSpecFacts("alpha");if e!=nil||f.Freshness.Status!=SpecFactsFresh||f.Freshness.Generation!=receipt.GenerationID||len(f.Checks)!=1||f.Paths[0].Path!="api/server.go"{t.Fatalf("not reproduced %+v %v",f,e)}
 current,e:=s.DeriveSpecFacts("alpha");if e!=nil||len(current.Checks)!=0{t.Fatalf("control %+v %v",current,e)}
 t.Logf("facts from %s name %s as fresh; old api still associated; current generation demotes it",old,f.Freshness.Generation)
}

